function v14FeedbackValidate(v){if(!v.place?.trim()||!v.type||!v.basis||!v.severity||String(v.content||'').trim().length<5)throw Error('请填写地点、类型、来源、自评与情况描述');if(!v.observed||!Number.isFinite(v11Date(v.observed).getTime())||v11Date(v.observed)>businessNow())throw Error('观测时间无效或晚于当前时刻');if(v.basis==='公开新闻／公告（非本人观测）'&&!v.source_url)throw Error('新闻来源请附上原文链接');if(v.source_url&&!/^https?:\/\//i.test(v.source_url))throw Error('依据链接仅支持http或https')}
async function v14SaveFeedback(v){v14FeedbackValidate(v);const active=V9.active,at=V2.at,photo=await vReadPhoto(v.photo);if(active!==V9.active||at!==V2.at)throw Error('场景已变化，请重新核对观测时间后提交');const rows=stored('sy-v2-feedback'),record={id:vId(),owner:V7.uid,type:v.type,place:v.place.trim(),observed:v.observed,basis:v.basis,severity:v.severity,content:v.content.trim(),source_url:v.source_url||'',photo,submitted:businessNow().toISOString(),actual_submitted_at:new Date().toISOString(),test_record:V9.active,demo:v.demo==='1',fiction_notice:v.demo==='1'?'根据当时情况编写 · 虚构演示':'',status:'待核验',_timeline:[{time:businessNow().toISOString(),state:{status:'待核验'}}]};rows.push(record);if(!save('sy-v2-feedback',rows))throw Error('本浏览器保存失败');return record}
function v14CreateTask(f){const duration=Number(f.duration),reward=Number(f.reward);if(!f.title?.trim()||!f.place?.trim()||String(f.detail||'').trim().length<10||!V7TYPES.includes(f.category)||!Number.isFinite(duration)||duration<1||duration>1440||!Number.isFinite(reward)||reward<0||reward>100000)throw Error('请填写任务标题、地点、内容、完成标准与有效时长／奖励');if(f.coordinates){const p=vResolve(f.coordinates);if(!p||![p.lat,p.lon].every(Number.isFinite)||p.regionOnly)throw Error('请填写有效的具体坐标')}if(f.deadline&&(!Number.isFinite(v11Date(f.deadline).getTime())||v11Date(f.deadline)<=businessNow()))throw Error('接单截止时刻必须有效且晚于现在');const now=businessNow().toISOString(),record={...f,title:f.title.trim(),place:f.place.trim(),detail:f.detail.trim(),duration,reward:f.rewardType==='无偿互助'?0:reward,id:vId(),source:'private',demo:f.demo==='1',fiction_notice:f.demo==='1'?'根据当时情况编写 · 虚构演示':'',source_url:f.demo==='1'?v14ExampleSource()?.source_url||'':'',owner:V7.uid,ownerName:V5.profile.name,created:now,actual_created_at:new Date().toISOString(),updated:now,status:'审核中',history:[]};delete record.myLocation;record.history.push({time:now,status:'审核中',action:'submit',snapshot:v14TaskState(record)});const rows=v7Rows();rows.push(record);if(!save('sy-v7-tasks',rows))throw Error('任务未能保存');V7.location=f.myLocation||V7.location;return record}
