document.addEventListener('submit',async e=>{const id=vFormId(e.target);if(!['v2-feedback','v7-task-form','v14-complete-form','v14-return-form','v14-software-form','v14-help-search'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();if(V14.busy)return;const f=Object.fromEntries(new FormData(e.target));v14Draft();V14.busy=true;try{if(id==='v2-feedback'){const r=await v14SaveFeedback(f);V14.feedbackDraft={};v14PersistDrafts();V14.skipDraftOnce=true;vRender();v14FeedbackDetail(r.id);toast('灾情反馈已保存，等待维护核验')}if(id==='v7-task-form'){v14CreateTask(f);V14.taskDraft={};v14PersistDrafts();V14.skipDraftOnce=true;V14.taskTab='mine';V7.filter='published';toast('任务已保存，等待维护审核');vRender()}if(id==='v14-complete-form'){await v14SubmitCompletion(f);document.getElementById('source-dialog')?.close();toast('材料已提交，等待发布者确认');vRender();v14TaskDetail(f.id)}if(id==='v14-return-form'){if(String(f.note||'').trim().length<5||!['return-work','reject'].includes(f.action||'return-work')||!v7SaveAction(f.id,f.action||'return-work',f.note))throw Error('请检查发布者身份、状态和退回原因');document.getElementById('source-dialog')?.close();toast(f.action==='reject'?'已记录审核未通过的原因':'已退回补充，接单者可重新提交');vRender()}if(id==='v14-software-form'){const r=await v14SaveSoftware(f);V14.softwareDraft={};v14PersistDrafts();V14.skipDraftOnce=true;V14.helpTab='records';toast('软件反馈已在本浏览器保存');vRender();v14SoftwareDetail(r.id)}if(id==='v14-help-search'){V14.helpQuery=f.query.trim();vRender()}}catch(err){toast(err.message||'未能保存，请检查输入')}finally{V14.busy=false}},true);
// Align legacy fictional examples to the same schema as the live disaster form.
function v14MigrateSamples(){const key='sandbox-sep2023:sy-v2-feedback',rows=v9StoreBase(key);let changed=false;for(const f of rows){if(!f.demo||!String(f.id).startsWith('v13-feedback-'))continue;const index=Number(f.id.split('-').at(-1));if(['公告核对','社区需求','信息整理'].includes(f.type)){f.type=index===0?'交通受限':'其他现场情况';changed=true}if(f.severity==='演示自评 · 一般影响'){f.severity='一般影响';changed=true}if(f.basis!== '公开新闻／公告（非本人观测）'&&f.basis?.includes('根据当时情况编写')){f.basis='公开新闻／公告（非本人观测）';changed=true}if(!f.v15_migrated){if(!f._timeline||f._timeline.every(h=>Date.parse(h.time)<=Date.parse('2023-09-08T09:29:00+08:00'))){f.status=['核验中','已核验','已更新'][index]||f.status;f.conclusion=index?'属实（核对范围内）':'尚未形成结论';f.handling_note=index?'演示核验：公开公告包含相应信息，仅限原文范围。':'演示维护人员正在核对原文。';f.evidence_url=f.source_url;f.resolution=index===2?'演示回复：先远程联系目的地，非必要外出延后。':'';f.handled_at='2023-09-08T09:29:00+08:00';f._timeline=[{time:f.submitted,state:{status:'待核验'}},{time:f.handled_at,state:v9StateOf(f)}]}f.v15_migrated=true;changed=true}if(f.status==='处理中'){f.status='核验中';changed=true}for(const h of f._timeline||[])if(h.state.status==='处理中'){h.state.status='核验中';changed=true}}if(changed)v9SaveBase(key,rows)}
const v14SeedBase=v13Seed;v13Seed=function(){v14SeedBase();v14MigrateSamples()};

