function v14ExampleDraft(){const src=v14ExampleSource();return {demo:'1',type:'交通受限',place:'罗湖',observed:v14LocalNow(),severity:'一般影响',basis:src?'公开新闻／公告（非本人观测）':'转述，尚未核实',source_url:src?.source_url||'',content:'【根据2023年暴雨当时情况编写 · 虚构演示】家庭计划从罗湖前往深圳人民医院，希望整理已发布的地铁运营公告及远程联络渠道。本例未作现场观测，不表示医院停诊或当前有积水。'}}
function v14SeedCurrent(){if(V9.active)return;const marker='sy-v15-current-examples';if(v9StoreBase(marker)?.created)return;const src=D.events.find(e=>e.record_id==='SZ-E022'),time=new Date().toISOString(),note='根据2023年暴雨当时情况编写 · 虚构演示；不是当前实况',feedback=['核验中','已核验','已更新'].map((status,i)=>({id:'v15-feedback-'+i,type:i?'其他现场情况':'交通受限',place:['罗湖','老街','深圳人民医院'][i],observed:time,submitted:time,demo:true,fiction_notice:note,basis:'公开新闻／公告（非本人观测）',severity:'一般影响',source_url:src?.source_url||'',content:['演示家庭请求整理地铁停运区段与原始公告。','演示维护人员核对公开报道中的减少外出建议。','演示就医家庭希望了解远程联系目的地的方法。'][i]+'【'+note+'】',status,conclusion:i?'属实（核对范围内）':'尚未形成结论',handling_note:i?'演示核验：只确认原文包含该公开信息，不确认现场水深或今天的运营状态。':'演示维护人员正在核对来源。',evidence_url:src?.source_url||'',resolution:i===2?'演示回复：非必要行程延后，必要就医先远程联系医院。':'',handled_at:time,_timeline:[{time,state:{status:'待核验'}},{time,state:{status,conclusion:i?'属实（核对范围内）':'尚未形成结论',handling_note:'根据当时情况编写的核验流程',resolution:i===2?'演示回复：整理公开就医联络方式，不代表已联系医院。':'',evidence_url:src?.source_url||''}}]}));const tasks=[['停运公告与区段整理','罗湖','其他','待接单',false,false],['室内远程帮助阅读通知','黄贝岭','设备协助','待接单',false,false],['就医公开联系方式校对','深圳人民医院','其他','审核中',true,false],['社区通知摘要排版','老街','其他','已接单',false,true],['公开公告来源校对','罗湖','其他','已完成',false,true],['机构通知格式整理','罗湖','其他','待接单',false,false]].map((x,i)=>{const t={id:'v15-task-'+i,title:x[0]+'（演示）',place:x[1],category:x[2],status:x[3],owner:x[4]?V7.uid:'v15-owner-'+i,ownerName:x[4]?V5.profile.name:'虚构演示发布者'+(i+1),worker:x[5]?V7.uid:undefined,workerName:x[5]?V5.profile.name:undefined,source:i===5?'official':'private',demo:true,fiction_notice:note,detail:'【'+note+'】在室内整理公开信息，交付包含地点、发布时间与原文链接的摘要。无需外出，不安排涉水作业。',rewardType:'无偿互助',reward:0,duration:15,difficulty:'简单',created:time,updated:time,source_url:src?.source_url||'',source_published_at:src?.source_published_at,completion:x[3]==='已完成'?'演示：已整理来源与区段摘要。':undefined};if(t.status==='已完成')t.completionPacket={summary:'根据当时情况编写：核对公告标题、发布时间与相关区段。',deliverable:'演示摘要：保留原文链接，列出线路区段和信息时间；不是实地观测。',link:src?.source_url||'',completedAt:time,actualMinutes:15,submittedAt:time,issue:'本例仅用于操作流程演示。'};t.history=[{time,status:t.status,note,snapshot:v14TaskState(t)}];return t});for(const [key,items] of [['sy-v2-feedback',feedback],['sy-v7-tasks',tasks]]){const rows=v9StoreBase(key);for(const item of items)if(!rows.some(r=>r.id===item.id))rows.push(item);v9SaveBase(key,rows)}v9SaveBase(marker,{created:time})}
function v14TaskReview(){const tasks=v7Rows().filter(t=>t.status==='审核中');return vHead('','任务审核','核对任务范围与交付要求，记录审核意见。')+`<section class="card">${tasks.map(t=>`<article class="v14reportcard">${v14TaskCard(t)}<div class="chips"><button data-v7="approve" data-value="${t.id}">审核通过</button><button data-v7="reject" data-value="${t.id}">退回并说明原因</button></div></article>`).join('')||'<p>暂无待审核任务。</p>'}</section>`}
function v14MaterialReview(){const rows=stored('sy-v9-reports');return vHead('','材料申请','整理灾情反馈的可导出材料；不是向官方提交。')+`<section class="card">${rows.map(r=>`<article class="v14reportcard"><b>${esc(r.place)}</b><p>${esc(r.content)}</p><span>${esc(r.status)}</span>${r.status==='待维护审核'?`<button data-v9="approve-report" data-value="${r.id}">审核为可导出材料</button>`:''}</article>`).join('')||'<p>暂无材料申请。历史场景中可从反馈记录申请整理材料。</p>'}</section>`}
v3Workspace=function(){const feedback=v3Feedback(),tasks=v7Rows(),software=stored('sy-v14-software-feedback'),reports=stored('sy-v9-reports');return vHead('','维护总览','查看待办数量，进入对应队列处理。')+`<div class="maintstats">${[['灾情待核验',feedback.filter(f=>['待核验','核验中'].includes(f.status)).length,'feedback'],['任务待审核',tasks.filter(t=>t.status==='审核中').length,'tasks'],['材料待审核',reports.filter(r=>r.status==='待维护审核').length,'materials'],['软件待处理',software.filter(r=>!['已解决','已关闭'].includes(r.status)).length,'software']].map(([title,n,page])=>`<article class="card"><small>${title}</small><b>${n}</b><button data-v3="page" data-value="${page}">打开处理队列 →</button></article>`).join('')}</div><section class="card"><h2>工作范围</h2><p>灾情核验处理地点、时间和依据；任务审核处理需求与交付标准；软件维护处理功能故障、界面建议与维护回复。</p><p class="muted">游客演示身份在本浏览器内共享记录。历史灾情按模拟时刻显示；软件记录始终使用实际时间。</p></section>`};
function v14SoftwareMaintenance(){const rows=stored('sy-v14-software-feedback');return vHead('','软件维护','功能问题与软件建议，使用实际时间记录处理。')+`<section class="card">${rows.slice().reverse().map(r=>`<article class="v14reportcard"><div class="row"><b data-original>${esc(r.title)}</b><span class="tag gray">${esc(r.status)}</span></div><p>${esc(r.kind)} · ${esc(r.module)} · ${esc(dateText(r.created))}</p><p data-original>${esc(r.detail)}</p>${r.reply?`<p>维护回复：${esc(r.reply)}</p>`:''}<button data-v14="software-handle" data-value="${r.id}">查看与回复</button></article>`).join('')||'<p>暂无软件反馈。用户可在独立的帮助页面提交软件问题。</p>'}</section><section class="card"><h2>维护记录原则</h2><p>说明复现结果、处理动作与建议；未修复的问题保持处理中，不能用灾情核验状态代替软件处理状态。</p></section>`}
function v14SoftwareHandle(id){if(V3.role!=='maintainer')return;const r=stored('sy-v14-software-feedback').find(x=>x.id===id);if(!r)return;vDialog('软件反馈处理',`<h3 data-original>${esc(r.title)}</h3>${[['问题描述',r.detail],['复现步骤',r.steps],['预期结果',r.expected],['实际结果',r.actual]].map(([k,v])=>`<h4>${k}</h4><p data-original>${esc(v||'未填写')}</p>`).join('')}${r.photo?`<img src="${r.photo}" alt="软件反馈截图" style="max-width:100%">`:''}<form id="v15-software-handle" class="feedbackform"><input type="hidden" name="id" value="${esc(id)}"><label>软件处理状态<select name="status">${['已在本浏览器保存','处理中','待用户补充','已解决','已关闭'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full">维护回复<textarea name="reply" required minlength="5">${esc(r.reply||'')}</textarea></label><button class="primary">保存状态与回复</button></form><p>使用真实当前时间；回复仅在本浏览器内显示。</p>`)}
document.addEventListener('submit',e=>{if(vFormId(e.target)!=='v15-software-handle')return;if(typeof V20!=='undefined')return;e.preventDefault();if(V3.role!=='maintainer')return;const f=Object.fromEntries(new FormData(e.target));if(!['已在本浏览器保存','处理中','待用户补充','已解决','已关闭'].includes(f.status)||String(f.reply||'').trim().length<5)return toast('请选择状态并填写具体回复');const rows=stored('sy-v14-software-feedback'),r=rows.find(x=>x.id===f.id);if(!r)return;const now=new Date().toISOString();r.status=f.status;r.reply=f.reply.trim();r.updated=now;r.history=[...(r.history||[]),{time:now,status:f.status,reply:r.reply}];if(save('sy-v14-software-feedback',rows)){if(typeof v16Notify==='function')v16Notify('software','软件维护回复',r.title+'：'+r.reply);document.getElementById('source-dialog')?.close();vRender();toast('软件处理与回复已保存')}else toast('保存失败，当前回复仍保留，请重试。')},true);


