document.addEventListener('click',e=>{const b=e.target.closest('[data-v7="accept"],[data-v7="cancel"],[data-v7="approve"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const t=v7Rows().find(x=>x.id===b.dataset.value),action=b.dataset.v7,error=v14TaskError(t,action);if(error)return toast(error);if(!v7SaveAction(b.dataset.value,action))return toast('当前身份或任务阶段不允许此操作，未修改记录');if(action==='accept'){V14.taskTab='mine';V7.filter='accepted';toast('已接单，可在我的任务提交完成材料')}else toast(action==='approve'?'审核通过，任务进入待接单':'任务已取消，历史记录保留');vRender()},true);
